import hashlib,pathlib,rbd

def export_snapshot(io,name,snapshot,path):
    digest=hashlib.sha256()
    with rbd.Image(io,name,snapshot=snapshot,read_only=True) as image:
        size=image.size()
        with pathlib.Path(path).open('xb') as stream:
            for offset in range(0,size,1024*1024):
                block=image.read(offset,min(1024*1024,size-offset));stream.write(block);digest.update(block)
    return {'bytes':size,'sha256':digest.hexdigest()}

def restore(io,name,path,manifest):
    data=pathlib.Path(path).read_bytes()
    if len(data)!=manifest['bytes'] or hashlib.sha256(data).hexdigest()!=manifest['sha256']:raise ValueError('backup integrity mismatch')
    rbd.RBD().create(io,name,len(data),order=22,old_format=False,features=rbd.RBD_FEATURE_LAYERING)
    with rbd.Image(io,name) as image:image.write(data,0);image.flush()

